JavaScript function "formatShortcut"
in delta-ai-extension/dashboard/dashboard.js
Purpose: formatShortcut(e), testing, configuration

/* ---- Shortcut config ---- */

function formatShortcut(e) {
  const parts = [];
  if (isMac && e.metaKey) parts.push('Command');
  if (e.ctrlKey) parts.push(isMac ? 'MacCtrl' : 'Ctrl');
  if (e.altKey) parts.push('Alt');
  if (e.shiftKey) parts.push('Shift');

  let key = e.key;
  if (['Control', 'Alt', 'Shift', 'Meta'].includes(key)) return null;

  if (key === ' ') key = 'Space';
  else if (key.length === 1) key = key.toUpperCase();

  const isFuncKey = /^F([1-9]|1[0-9])$/.test(key);
  if (!isFuncKey && parts.length === 0) return null;

  parts.push(key);
  return parts.join('+');
}

